      en: ["Daily traffic: 50 trucks and 30 cars.", "Annual customs revenue: $3 million.", "Operating hours: 06:00-18:00.", "Distance to Dedza: 15 km.", "Processed 18,000 vehicles in 2021.", "Main commodities: maize, tobacco, groundnuts."],
      es: ["Tráfico diario: 50 camiones.", "Horario: 6:00 a 18:00 horas.", "Recaudación aduanera anual: 3 millones de USD.", "Distancia a Dedza: 15 km.", "Mercancía principal: productos agrícolas.", "La carretera hacia Milange (Mozambique) es de grava."],
      pt: ["Volume de tráfego diário: 50 camiões.", "Horário: 06:00 às 18:00.", "Receita aduaneira anual: 3 milhões de USD.", "Distância para Dedza: 15 km.", "Mercadoria exclusiva: produtos agrícolas.", "A estrada para Milange (Moçambique) é de terra batida."],
      fr: ["Trafic quotidien : 50 camions.", "Heures d'ouverture : 6h00 à 18h00.", "Recettes douanières annuelles : 3 millions USD.", "Distance de Dedza : 15 km.", "Produits échangés : produits agricoles.", "La route vers Milange (Mozambique) est une piste de gravier."],
